  (* [comment removed for export] *)
  Section JRD.
    Variables (mm : word -> option byte) (fjunk : list byte).
    Hypothesis MIm : mem_inv asegs mm.
    Hypothesis SRCm : bytes_at asegs mm (bv_unsigned a1) src.
    Hypothesis DSTm : rw_cells asegs mm (bv_unsigned a0) [CB (Z.to_nat (bv_unsigned a2)) junk].
    Hypothesis FR1 : FRAME mm.
    Hypothesis FR : rw_cells asegs mm (bv_unsigned sp + -2144) [CB 2072 fjunk].
    Hypothesis STm : stk asegs mm lo (bv_unsigned sp + -2144).
    Hypothesis MU : munch W m mm.
    Hypothesis WM : wmono asegs m mm.
    Hypothesis G1 : rw_cells asegs mm 1160136 [C8 (Z_to_bv 64 1217656)].
    Hypothesis C1 : rw_cells asegs mm 1217656 [C8 (Z_to_bv 64 2147450880)].
    Hypothesis G2 : rw_cells asegs mm 1160144 [C8 (Z_to_bv 64 1220968)].
    Hypothesis G3 : rw_cells asegs mm 1160152 [C8 (Z_to_bv 64 1220976)].
    Hypothesis G4 : rw_cells asegs mm 1160160 [C8 (Z_to_bv 64 1220960)].
    Hypothesis C4 : rw_cells asegs mm 1220960 [C8 (Z_to_bv 64 (2 ^ 47 - 1)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)].

